SystemVerilog:
module <module_name>(input <logic/logic[3:0]> <name1>, <name2>, <name3>, ..., output <logic/logic[3:0]> <name1>, <name2>, <name3>, …);
    assign <name> = <expr>;
    <statements>;
endmodule

VHDL:
library IEEE; use IEEE.STD_LOGIC_1164.all; (library use clause)

(entity declaration: lists its inputs and outputs)
entity <name> is
    port(<name1>, <name2>, <name3>: in <STD_LOGIC/STD_LOGIC_VECTOR(3 downto 0)>;
        <name4>, <name5>, <name6>, …: out STD_LOGIC <STD_LOGIC/STD_LOGIC_VECTOR(3 downto 0)>);
end;

(architecture body defines module functionality)
architecture synth of <name> is
begin
    <name> <= expr;
    <statement>;
end;

