SystemVerilog:
module tristate (
    input  logic [3:0] a,
    input  logic       en,
    output tri   [3:0] y
);
    assign y = en ? a : 4'bz;
endmodule

VHDL:
library IEEE;
use IEEE.STD_LOGIC_1164.ALL;

entity tristate is
    port (
        a  : in  STD_LOGIC_VECTOR(3 downto 0);
        en : in  STD_LOGIC;
        y  : out STD_LOGIC_VECTOR(3 downto 0)
    );
end tristate;

architecture synth of tristate is
begin
    y <= a when en else (others => 'Z');
end synth;

SystemVerilog:
module gates(input logic[3:0] a, b, output logic[3:0] y1, y2, y3, y4, y5);
    assign y1 = a&b;
    assign y2 = a|b;
    assign y3 = a^b;
    assign y4 = ~(a&b);
    assign y5 = ~(a|b);
endmodule

VHDL:
library IEEE;
use IEEE.STD_LOGIC_1164.ALL;

entity gates is
    port (
        a, b : in  STD_LOGIC_VECTOR(3 downto 0);
        y1, y2, y3, y4, y5 : out STD_LOGIC_VECTOR(3 downto 0)
    );
end gates;

architecture synth of gates is
begin
    -- Five different two-input logic gates acting on 4-bit buses
    y1 <= a and b;
    y2 <= a or b;
    y3 <= a xor b;
    y4 <= a nand b;
    y5 <= a nor b;
end synth;

SystemVerilog:
module fulladder (
    input  logic a, b, cin,
    output logic s, cout
);
    logic p, g;

    assign p    = a ^ b;
    assign g    = a & b;
    assign s    = p ^ cin;
    assign cout = g | (p & cin);
endmodule

VHDL:
library IEEE;
use IEEE.STD_LOGIC_1164.ALL;

entity fulladder is
    port (
        a, b, cin : in  STD_LOGIC;
        s, cout   : out STD_LOGIC
    );
end fulladder;

architecture synth of fulladder is
    signal p, g : STD_LOGIC;
begin
    p    <= a xor b;
    g    <= a and b;
    s    <= p xor cin;
    cout <= g or (p and cin);
end synth;

SystemVerilog:
module example(input logic a, b, c, output logic y);
    assign y = ~a & ~b & ~c | a & ~b & ~c | a & ~b & c;
endmodule

module sevenseg(input logic [3:0] data, output logic [6:0] segments);
    always_comb
        case (data)
            0: segments = 7'b111_1110;
            1: segments = 7'b011_0000;
            2: segments = 7'b110_1101;
            3: segments = 7'b111_1001;
            4: segments = 7'b011_0011;
            5: segments = 7'b101_1011;
            6: segments = 7'b101_1111;
            7: segments = 7'b111_0000;
            8: segments = 7'b111_1111;
            9: segments = 7'b111_0111;
            default: segments = 7'b000_0000;
        endcase
endmodule

module example(input logic s, s0, s1, output logic y);
    assign y = s ? S1 : s0;
endmodule
